 "path": "/payment_cards",
 "method": "POST",
 "description": "Add a new payment card.",
 "parameters": [
  {
   "name": "card_name",
   "type": "string",
   "required": true,
   "description": "Name of the payment card.",
   "default": null,
   "constraints": [
    "length >= 1"
   ]
  },
  {
   "name": "owner_name",
   "type": "string",
   "required": true,
   "description": "Full name of the owner of the payment card.",
   "default": null,
   "constraints": [
    "length >= 1"
   ]
  },
  {
   "name": "card_number",
   "type": "integer",
   "required": true,
   "description": "16-digit card number.",
   "default": null,
   "constraints": [
    "value >= 1000000000000000.0, < 1e+16"
   ]
  },
  {
   "name": "expiry_year",
   "type": "integer",
   "required": true,
   "description": "Expiration year of the payment card.",
   "default": null,
   "constraints": []
  },
  {
   "name": "expiry_month",
   "type": "integer",
   "required": true,
   "description": "Expiration month of the payment card.",
   "default": null,
   "constraints": [
